// The rules of the first-run setup, in the browser. They mirror backend/onboarding.py exactly (flow.test.ts checks the two against
// the same cases, generated by the server's own tests), so the page never shows a question the server would refuse, and never
// hides one it would accept. The server stays the authority: it re-checks every answer.

export type QuestionType = "text" | "date" | "single" | "multi" | "slider" | "faces" | "number_pair";

export interface Rule {
  age_gte?: number;
  age_lt?: number;
  body_in?: string[];
  answers?: Record<string, string[]>;
  not_answers?: Record<string, string[]>;
}

export interface Option {
  id: string;
  label: string;
  show_if?: Rule;
}

export interface Question {
  id: string;
  step: string;
  type: QuestionType;
  title: string;
  why: string;
  required: boolean;
  options?: Option[];
  show_if?: Rule;
  exclusive?: string[];
  max_picks?: number;
  maxlength?: number;
  min?: number;
  max?: number;
  increment?: number;
  unit?: string;
}

export interface Step {
  id: string;
  title: string;
  intro: string;
  extra?: boolean;
}

export type Answers = Record<string, unknown>;

const MS_PER_DAY = 86_400_000;

/** Whole years on `today` for a YYYY-MM-DD birth date, or null when it is not a real past day. */
export function ageOn(birth: unknown, today: Date): number | null {
  if (typeof birth !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(birth)) return null;
  const [y, m, d] = birth.split("-").map(Number);
  const born = new Date(y, m - 1, d);
  if (born.getFullYear() !== y || born.getMonth() !== m - 1 || born.getDate() !== d) return null;
  const start = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  if (born.getTime() > start.getTime()) return null;
  return today.getFullYear() - y - (today.getMonth() < m - 1 || (today.getMonth() === m - 1 && today.getDate() < d) ? 1 : 0);
}

export function picked(value: unknown): string[] {
  if (Array.isArray(value)) return value.map(String);
  return value === undefined || value === null || value === "" ? [] : [String(value)];
}

/** Every part of the rule must hold. A part that depends on an unanswered question does not hold, except `not_answers`. */
export function matches(rule: Rule | undefined, answers: Answers, today: Date): boolean {
  if (!rule) return true;
  const age = ageOn(answers.birth_date, today);
  if (rule.age_gte !== undefined && (age === null || age < rule.age_gte)) return false;
  if (rule.age_lt !== undefined && (age === null || age >= rule.age_lt)) return false;
  if (rule.body_in && !rule.body_in.includes(String(answers.body))) return false;
  for (const [qid, ids] of Object.entries(rule.answers ?? {})) {
    if (!picked(answers[qid]).some((p) => ids.includes(p))) return false;
  }
  for (const [qid, ids] of Object.entries(rule.not_answers ?? {})) {
    if (picked(answers[qid]).some((p) => ids.includes(p))) return false;
  }
  return true;
}

export const visibleOptions = (q: Question, answers: Answers, today: Date): Option[] => (q.options ?? []).filter((o) => matches(o.show_if, answers, today));
export const visibleQuestions = (questions: readonly Question[], answers: Answers, today: Date): Question[] => questions.filter((q) => matches(q.show_if, answers, today));

/** Steps that have at least one visible question, in order. */
export function activeSteps(steps: readonly Step[], questions: readonly Question[], answers: Answers, today: Date): Step[] {
  const shown = new Set(visibleQuestions(questions, answers, today).map((q) => q.step));
  return steps.filter((s) => shown.has(s.id));
}

export function isAnswered(q: Question, value: unknown): boolean {
  if (value === undefined || value === null || value === "") return false;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === "object") return Object.keys(value as object).length > 0;
  return true;
}

/** Visible, required questions of a step that are still empty. */
export function missingRequired(stepQuestions: readonly Question[], answers: Answers): string[] {
  return stepQuestions.filter((q) => q.required && !isAnswered(q, answers[q.id])).map((q) => q.id);
}

/** The answer after tapping `optionId`: single replaces, multi adds or removes, and "None of these" style options stand alone. */
export function pick(q: Question, current: unknown, optionId: string): unknown {
  if (q.type === "single") return current === optionId ? undefined : optionId;
  const now = picked(current);
  if (now.includes(optionId)) {
    const rest = now.filter((p) => p !== optionId);
    return rest.length ? rest : undefined;
  }
  if ((q.exclusive ?? []).includes(optionId)) return [optionId];
  const without = now.filter((p) => !(q.exclusive ?? []).includes(p));
  if (q.max_picks !== undefined && without.length >= q.max_picks) return without;
  return [...without, optionId];
}

/** Answers of one step as a PUT patch: what is answered, and null for an optional question left empty (a skip). */
export function stepPatch(stepQuestions: readonly Question[], answers: Answers): Record<string, unknown> {
  const patch: Record<string, unknown> = {};
  for (const q of stepQuestions) patch[q.id] = isAnswered(q, answers[q.id]) ? answers[q.id] : q.required ? undefined : null;
  return Object.fromEntries(Object.entries(patch).filter(([, v]) => v !== undefined));
}

/** The title in the person's language when the bank has one (Hinglish), else English. */
export function titleFor(q: Question, language: unknown, hinglish: Record<string, string>): string {
  return language === "hinglish" || language === "hindi" ? hinglish[q.id] ?? q.title : q.title;
}

export const dayMs = MS_PER_DAY;
